using SupportAgent.Core.BusinessQuery;
using SupportAgent.Core.ExternalData;
using SupportAgent.Infrastructure.BusinessQuery;
using SupportAgent.Infrastructure.ExternalData;
namespace SupportAgent.Tests;

public sealed class Phase141DynamicExternalSchemaTests
{
 [Fact] public void Arbitrary_legacy_names_compile_from_metadata_only(){var entity=Entity("x_hdr","SalesDocuments",("x_no","DocumentNumber"),("x_total","Total"));var plan=new BusinessQueryPlan{Entity="SalesDocuments",Select=["DocumentNumber","Total"],Limit=10};var compiled=new SqlServerBusinessQueryCompiler().Compile(plan,Schema(entity),[entity],[]);Assert.Contains("[dbo].[x_hdr]",compiled.CommandText);Assert.Contains("[t0].[x_no] AS [DocumentNumber]",compiled.CommandText);Assert.DoesNotContain("Invoices",compiled.CommandText);}
 [Fact] public void Invalid_drifted_mapping_fails_before_sql_execution(){var entity=Entity("m_stock","Inventory",("qty","Quantity"));entity.IsValid=false;var plan=new BusinessQueryPlan{Entity="Inventory",Select=["Quantity"]};var ex=Assert.Throws<ExternalDataException>(()=>new SqlServerBusinessQueryCompiler().Compile(plan,Schema(entity),[entity],[]));Assert.Equal("SchemaDrift",ex.Code);Assert.DoesNotContain("SQL",ex.Message,StringComparison.OrdinalIgnoreCase);}
 [Fact] public void Unapproved_fields_and_relationships_cannot_be_injected(){var entity=Entity("m_client","Clients",("client_name","Name"));var plan=new BusinessQueryPlan{Entity="Clients",Select=["PasswordHash"]};Assert.Throws<ExternalDataException>(()=>new SqlServerBusinessQueryCompiler().Compile(plan,Schema(entity),[entity],[]));}
 [Fact] public void Selector_reduces_large_dynamic_schema_using_logical_metadata(){var tables=Enumerable.Range(1,100).Select(i=>new BusinessTableSchema($"Entity{i}",$"Entity {i}","Unrelated records",["misc"],[new("Id","ID","Identifier","Integer")])).ToList();tables[42]=new("SalesDocuments","Sales documents","Revenue and invoice records",["sales","invoice","revenue"],[new("CustomerCode","Customer","Customer reference","String",Concepts:["customer"])]);tables[73]=new("Clients","Customers","Customer master",["customer","client"],[new("Code","Code","Customer code","String")]);var selector=new BusinessSchemaSelector(new StaticSchema(new(tables,[new("SalesDocuments","CustomerCode","Clients","Code")])));var selected=selector.Select("Which customers have the highest sales?");Assert.Equal(2,selected.Entities.Count);Assert.Contains(selected.Entities,x=>x.Name=="SalesDocuments");Assert.Contains(selected.Entities,x=>x.Name=="Clients");}
 [Fact] public void Discovery_metadata_supports_views_pk_fk_and_deny_by_default(){var fk=new ExternalDiscoveredForeignKey("FK_x","dbo","x_dtl","hdr_id","dbo","x_hdr","id");var view=new ExternalDiscoveredObject("reports","vw_monthly_sales","VIEW",[new("id","bigint",false,true,true),new("hdr_id","bigint",false,false,true,true)],[fk]);Assert.Equal("VIEW",view.ObjectType);Assert.True(view.Columns[0].PrimaryKey);Assert.True(view.Columns[1].ForeignKey);Assert.Empty(new List<ExternalEntityMapping>());}
 static ExternalEntityMapping Entity(string physical,string logical,params(string Physical,string Logical)[] fields)=>new(){Id=Guid.NewGuid(),ExternalSchemaName="dbo",ExternalTableName=physical,BusinessEntityName=logical,DisplayName=logical,IsEnabled=true,IsValid=true,Fields=fields.Select(x=>new ExternalFieldMapping{Id=Guid.NewGuid(),ExternalColumnName=x.Physical,BusinessFieldName=x.Logical,DisplayName=x.Logical,DataType="String",IsQueryable=true}).ToList()};
 static BusinessSchema Schema(ExternalEntityMapping e)=>new([new(e.BusinessEntityName,e.DisplayName,"",[],e.Fields.Select(x=>new BusinessColumnSchema(x.BusinessFieldName,x.DisplayName,"",x.DataType)).ToList())],[]);
 sealed class StaticSchema(BusinessSchema schema):IBusinessSchemaService{public BusinessSchema GetSchema()=>schema;}
}
